'use strict';
// Guided pattern matching only; compilation happens separately in the embedded editor.
(function(root){
  const ISSUES={
    semicolon:{title:['Pode faltar um ponto e vírgula','A semicolon may be missing'],why:['Instruções simples em Java terminam com ;. O compilador às vezes aponta a linha seguinte.','Simple Java statements end with ;. The compiler may point to the following line.'],hints:[['Encontre a instrução completa perto da linha indicada.','Find the complete statement near the indicated line.'],['Veja o fim de uma declaração, atribuição ou chamada.','Check the end of a declaration, assignment, or call.'],['Experimente ; no fim da instrução e compile novamente.','Try ; at the end of the statement and compile again.']],quiz:['Qual linha imprime Olá corretamente?','Which line prints Olá correctly?',['System.out.println("Olá")','System.out.println("Olá");','System.out.println("Olá"):'],1,'A chamada termina com ;.','The call ends with ;.']},
    symbol:{title:['Um nome não foi encontrado','A name was not found'],why:['Compare o nome usado com a declaração. Java distingue maiúsculas, minúsculas e escopo. Também pode faltar um import.','Compare the name with its declaration. Java is case-sensitive; scope or an import may be the cause.'],hints:[['Leia o nome após “symbol” na mensagem.','Read the name after “symbol” in the message.'],['Procure a declaração e compare letra por letra.','Find the declaration and compare character by character.'],['Confira o escopo da variável ou o import da classe.','Check variable scope or the class import.']],quiz:['Qual linha usa total corretamente?','Which line uses total correctly?',['int total=3; System.out.println(totla);','int total=3; System.out.println(total);','int total=3; System.out.println(Total);'],1,'Os nomes precisam ser iguais.','Names must match exactly.']},
    types:{title:['Os tipos não combinam','The types do not match'],why:['O valor fornecido não cabe no tipo esperado. Confira aspas, números e conversões.','The supplied value does not fit the expected type. Check quotes, numbers, and conversions.'],hints:[['Leia os tipos citados no erro.','Read the types named in the error.'],['Compare o tipo da variável com o valor atribuído.','Compare the variable type with the assigned value.'],['Escolha o tipo adequado ou uma conversão explícita segura.','Choose the right type or a safe explicit conversion.']],quiz:['Qual declaração guarda texto?','Which declaration stores text?',['int idade="22";','String idade="22";','boolean idade="22";'],1,'Aspas duplas produzem String.','Double quotes produce a String.']},
    null:{title:['Um objeto pode estar nulo','An object may be null'],why:['NullPointerException indica uso de algo que vale null. Procure onde o objeto deveria receber valor.','NullPointerException means code used an object whose value is null. Find where it should be assigned.'],hints:[['Leia a primeira linha do seu código no stack trace.','Read the first line of your code in the stack trace.'],['Volte até a criação ou atribuição do objeto.','Trace back to object creation or assignment.'],['Inicialize o objeto ou trate null antes de acessá-lo.','Initialize the object or handle null before accessing it.']],quiz:['Qual condição evita chamar length() em null?','Which condition avoids calling length() on null?',['if(nome!=null) System.out.println(nome.length());','if(nome==null) System.out.println(nome.length());','System.out.println(nome.length());'],0,'Verifique antes de acessar.','Check before accessing.']},
    bounds:{title:['Índice fora dos limites','Index out of bounds'],why:['Um array com length itens aceita índices de 0 até length - 1.','An array with length items accepts indices from 0 to length - 1.'],hints:[['Encontre o acesso com colchetes na linha apontada.','Find the bracket access on the reported line.'],['Compare o índice usado com o tamanho do array.','Compare the index with the array length.'],['Em laços, teste i < array.length.','In loops, test i < array.length.']],quiz:['Qual condição percorre um array inteiro?','Which condition traverses the whole array?',['i <= numeros.length','i < numeros.length','i == numeros.length'],1,'O último índice é length - 1.','The last index is length - 1.']},
    number:{title:['Texto não pôde virar número','Text could not be parsed as a number'],why:['NumberFormatException significa que o texto recebido não tem o formato esperado.','NumberFormatException means the input text has an unexpected format.'],hints:[['Veja “For input string” no erro.','Look for “For input string” in the error.'],['Compare o texto com o formato de parseInt ou parseDouble.','Compare the text with parseInt or parseDouble requirements.'],['Valide a entrada ou trate a exceção.','Validate the input or handle the exception.']],quiz:['Qual texto parseInt aceita?','Which text can parseInt accept?',['"vinte"','"20.5"','"20"'],2,'Um inteiro em texto usa dígitos, como 20.','An integer string uses digits such as 20.']},
    braces:{title:['Confira os delimitadores do bloco','Check block delimiters'],why:['Uma chave, parêntese ou colchete pode estar sem par. O erro pode aparecer longe da causa.','A brace, parenthesis, or bracket may be unmatched. The error can surface later.'],hints:[['Comece pelo bloco próximo da linha indicada.','Start with the block near the reported line.'],['Indente classe, método e decisões separadamente.','Indent class, method, and decisions separately.'],['Cada { fecha com }, cada ( com ) e cada [ com ].','Each { closes with }, ( with ), and [ with ].']],quiz:['O que fecha um bloco iniciado com { ?','What closes a block opened with { ?',[')',']','}'],2,'Chaves delimitam blocos.','Braces delimit blocks.']},
    string:{title:['O texto pode estar sem aspas de fechamento','Text may lack a closing quote'],why:['Uma String precisa começar e terminar com aspas duplas.','A String must start and end with double quotes.'],hints:[['Ache a primeira aspa na linha.','Find the first quote on the line.'],['Confira se existe a segunda aspa.','Check for the second quote.'],['Feche o texto antes de ); e compile novamente.','Close the text before ); and compile again.']],quiz:['Qual linha contém uma String fechada?','Which line has a closed String?',['System.out.println("Oi);','System.out.println("Oi");','System.out.println(Oi");'],1,'Oi aparece entre aspas duplas.','Oi is between double quotes.']},
    main:{title:['Confira a entrada do programa','Check the program entry point'],why:['Um programa tradicional inicia em public static void main(String[] args). O nome main usa m minúsculo.','A traditional program starts at public static void main(String[] args). main uses lowercase m.'],hints:[['Leia o detalhe sobre “main method”.','Read the “main method” detail.'],['Compare o nome e os parâmetros com a assinatura esperada.','Compare name and parameters with the expected signature.'],['Escreva a assinatura dentro da classe inicial.','Write the signature inside the entry class.']],quiz:['Qual assinatura é válida?','Which signature is valid?',['public void Main(String args)','public static void main(String[] args)','static int main()'],1,'main usa static, void e String[].','main uses static, void, and String[].']},
    logic:{title:['Vamos investigar a lógica','Let’s investigate the logic'],why:['Nenhum padrão conhecido apareceu. Isso não prova que o programa está correto; compare entradas e saídas.','No known pattern appeared. That does not prove the program is correct; compare inputs and outputs.'],hints:[['Anote entrada, saída esperada e saída obtida.','Write down input, expected output, and actual output.'],['Imprima valores antes e depois da condição ou do laço.','Print values before and after the condition or loop.'],['Teste a menor entrada que reproduz o problema.','Test the smallest input that reproduces the problem.']],quiz:['O código roda mas dá resposta errada. O que ajuda primeiro?','Code runs but gives the wrong result. What helps first?',['Mudar valores ao acaso','Comparar entrada, esperado e obtido','Apagar o código'],1,'A comparação mostra onde o comportamento diverge.','Comparison shows where behavior diverges.']}
  };
  const SAMPLES=[
    {name:['Ponto e vírgula','Semicolon'],code:'public class Main {\n  public static void main(String[] args) {\n    System.out.println("Olá")\n  }\n}',error:"Main.java:3: error: ';' expected"},
    {name:['Nome trocado','Misspelled name'],code:'public class Main {\n  public static void main(String[] args) {\n    int total=3;\n    System.out.println(totla);\n  }\n}',error:'Main.java:4: error: cannot find symbol\n  symbol: variable totla'},
    {name:['Objeto nulo','Null object'],code:'public class Main {\n  public static void main(String[] args) {\n    String nome=null;\n    System.out.println(nome.length());\n  }\n}',error:'java.lang.NullPointerException\n at Main.main(Main.java:4)'},
    {name:['Fim do array','Array boundary'],code:'public class Main {\n  public static void main(String[] args) {\n    int[] n={1,2,3};\n    for(int i=0;i<=n.length;i++) System.out.println(n[i]);\n  }\n}',error:'java.lang.ArrayIndexOutOfBoundsException: Index 3 out of bounds for length 3\n at Main.main(Main.java:4)'},
    {name:['Tipos diferentes','Type mismatch'],code:'public class Main {\n  public static void main(String[] args) {\n    int idade="22";\n  }\n}',error:'Main.java:3: error: incompatible types: String cannot be converted to int'},
    {name:['Entrada inválida','Invalid input'],code:'public class Main {\n  public static void main(String[] args) {\n    int n=Integer.parseInt("vinte");\n    System.out.println(n);\n  }\n}',error:'java.lang.NumberFormatException: For input string: "vinte"\n at Main.main(Main.java:3)'},
    {name:['Chave sem par','Unmatched brace'],code:'public class Main {\n  public static void main(String[] args) {\n    System.out.println("Olá");\n  }',error:'Main.java:4: error: reached end of file while parsing'},
    {name:['Aspas sem fechar','Unclosed string'],code:'public class Main {\n  public static void main(String[] args) {\n    System.out.println("Olá);\n  }\n}',error:'Main.java:3: error: unclosed string literal'},
    {name:['Método principal','Main method'],code:'public class Main {\n  public static void Main(String[] args) {\n    System.out.println("Olá");\n  }\n}',error:'Error: Main method not found in class Main, please define the main method as: public static void main(String[] args)'},
    {name:['Resultado inesperado','Unexpected result'],code:'public class Main {\n  public static void main(String[] args) {\n    int[] valores={1,2,3};\n    int soma=0;\n    for(int i=0;i<valores.length-1;i++) soma+=valores[i];\n    System.out.println(soma);\n  }\n}',error:'Entrada: 1, 2, 3\nEsperado: 6\nObtido: 3'}
  ];
  function pairs(code){let state='code',line=1,stack=[],mismatch=null;const opposite={')':'(',']':'[','}':'{'};for(let i=0;i<code.length;i++){const c=code[i],n=code[i+1];if(c==='\n'){line++;if(state==='line')state='code';continue}if(state==='line')continue;if(state==='block'){if(c==='*'&&n==='/'){state='code';i++}continue}if(state==='string'||state==='char'){if(c==='\\'){i++;continue}if(c===(state==='string'?'"':"'"))state='code';continue}if(c==='/'&&n==='/'){state='line';i++;continue}if(c==='/'&&n==='*'){state='block';i++;continue}if(c==='"'||c==="'"){state=c==='"'?'string':'char';continue}if('({['.includes(c))stack.push({char:c,line});else if(')}]'.includes(c)){const open=stack.pop();if(!open||open.char!==opposite[c]){mismatch=line;break}}}return {braces:mismatch||stack.at(-1)?.line||null,string:state==='string'?line:null}}
  function analyze(source,diagnostic){const code=String(source||'').slice(0,40000),error=String(diagnostic||'').slice(0,10000),lines=code.split('\n'),out=[],match=error.match(/(?:\.java:|line\s+)(\d+)/i),reported=match?Number(match[1]):null;function add(id,origin,line){if(!out.some(x=>x.id===id))out.push({id,origin,line:line||reported||null})}
    if(/unclosed string literal/i.test(error))add('string','error');
    if(/';' expected|missing semicolon/i.test(error))add('semicolon','error');
    if(/cannot find symbol|cannot resolve symbol/i.test(error))add('symbol','error');
    if(/incompatible types|cannot be converted to|possible lossy conversion/i.test(error))add('types','error');
    if(/NullPointerException/i.test(error))add('null','error');
    if(/ArrayIndexOutOfBoundsException|IndexOutOfBoundsException/i.test(error))add('bounds','error');
    if(/NumberFormatException/i.test(error))add('number','error');
    if(/main method not found|NoSuchMethodError: main/i.test(error))add('main','error');
    if(/reached end of file while parsing/i.test(error))add('braces','error');
    for(const [pattern,id] of [[/\bSystem\.out\.printIn\b|\bsystem\.out\.|\bSystem\.Out\./,'symbol'],[/\bpublic\s+static\s+void\s+Main\s*\(/,'main']]){const m=code.match(pattern);if(m)add(id,'code',code.slice(0,m.index).split('\n').length)}
    const p=pairs(code);if(p.string)add('string','code',p.string);if(p.braces)add('braces','code',p.braces);
    for(let i=0;i<lines.length;i++){const s=lines[i].trim();if(!s||/[;{}:]\s*(?:\/\/.*)?$/.test(s)||/^(?:\/\/|\*|#|@|if\b|for\b|while\b|switch\b|catch\b|else\b|try\b|do\b|class\b|public\s+class\b)/.test(s))continue;if(/(?:System\.out\.print|\b(?:int|long|double|String|boolean|char)\s+\w+\s*=|\breturn\s+|\bimport\s+)/.test(s)&&/(?:\)|"|\w|\])$/.test(s)){add('semicolon','code',i+1);break}}
    if(!out.length)add('logic','explore',null);
    return out.slice(0,4).map(x=>({...x,evidence:x.line&&lines[x.line-1]?lines[x.line-1].trim().slice(0,240):''}));
  }
  const api={ISSUES,SAMPLES,analyze};root.JavaSOSCore=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
